import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { useRowAction } from '../../api/rowAction';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { peoplePath, peopleQueryKey, type Person } from './people';

// A person's aliases — other names they go by, sorted ignoring case (the server sorts them) — and the entry and
// button that add another. An alias must not equal, ignoring case, any name or alias on the sheet or on another
// sheet of its tree (its ancestors and descendants).
function AliasesHeader() {
  return <th>Aliases</th>;
}

function PersonAliases({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [alias, setAlias] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { alias: string }) =>
      postJson<Person>(`${peoplePath(sheet ?? '')}/${person.id}/aliases`, body, user),
    onSuccess: () => {
      setAlias('');
      return queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') });
    },
  });
  const submit = useSubmitOnce(add);
  const rowAction = useRowAction(`person-${person.id}`);
  return (
    <td>
      <span data-testid="person-aliases">{(person.aliases ?? []).join(', ')}</span>{' '}
      <input
        data-testid="person-alias-input"
        placeholder="Alias"
        value={alias}
        onChange={(e) => { setAlias(e.target.value); add.reset(); }}
      />
      <button
        type="button"
        data-testid="person-alias-add"
        disabled={add.isPending}
        onClick={() => { rowAction.take(); submit({ alias }); }}
      >
        Add alias
      </button>
      {add.isError && rowAction.isLatest && (
        <span data-testid="person-error">The alias must not be blank, nor any name or alias on the sheet.</span>
      )}
    </td>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 6.5, Component: AliasesHeader }),
  PersonCells.fill({ order: 6.5, Component: PersonAliases }),
];
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** The people table's extra column headers: each contributes one or more `<th>`. */
export const PeopleColumns = defineSlot('people.columns');

/**
 * The people table's extra cells for one person's row, in the same order as PeopleColumns: each
 * contributes `<td>`s. Everything inside a person's row belongs to `person-row-<id>`.
 */
export const PersonCells = defineSlot<{ person: Person }>('people.cells');
import { useRef, useSyncExternalStore } from 'react';

// The last action taken on each row, by row key. A row's cells come from separate slots, each with its own
// mutation; an error belongs to the action that raised it, so it is shown only while that action is still the
// row's latest — taking the next action on the row, in any of its cells, removes an old error.
const latest = new Map<string, symbol>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

export function useRowAction(row: string) {
  const mine = useRef(Symbol(row));
  const current = useSyncExternalStore(subscribe, () => latest.get(row));
  return {
    /** Marks this cell's action as the row's latest; call it as the action is taken. */
    take: () => {
      latest.set(row, mine.current);
      listeners.forEach((l) => l());
    },
    /** Whether this cell's action is the row's latest, so its error may show. */
    isLatest: current === mine.current,
  };
}

